// ================= CONFIGURE AQUI =================
// Número do WhatsApp da agência no WTS/Frédy (de onde a mensagem sai), só números com 55.
const CANAL = "55DDDNUMERO";
// ID de cada modelo aprovado no WTS (Ajustes > Modelos). Deixe "" para não enviar aquele aviso.
const MODELOS = {
  "cliente.aniversario": "",
  "viagem.checkin": "",
  "viagem.concluida": "",
  "pagamento.vencendo": "",
  "pagamento.identificado": "",
};
// Para testar com o botão "Enviar evento de teste" do sistema: coloque aqui o SEU WhatsApp (com 55).
// Vazio = o evento de teste é recebido e conferido, mas nada é enviado.
const TESTE_PARA = "";
// ==================================================

const brl = (c) => ((c ?? 0) / 100).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const data = (s) => (s ? String(s).slice(0, 10).split("-").reverse().join("/") : "");
const out = [];

for (const item of $input.all()) {
  const body = item.json.body || {};
  const headers = item.json.headers || {};
  // 1) só aceita o que veio assinado pelo Frédy Gestão com o segredo combinado
  if (!headers["x-fredy-signature"] || headers["x-fredy-signature"] !== item.json.assinaturaCalculada) continue;
  const d = body.data || {};
  const c = d.client || {};
  // 2) respeita a autorização do cliente (LGPD) e precisa de WhatsApp
  if (!d.messagingAllowed || !c.whatsapp) continue;
  const templateId = MODELOS[body.type];
  if (!templateId) continue;
  let to = c.whatsapp;
  if (body.test) {
    if (!TESTE_PARA) continue;
    to = TESTE_PARA;
  }
  // 3) variáveis de cada modelo (os nomes precisam ser iguais aos do modelo no WTS)
  let parameters = {};
  switch (body.type) {
    case "cliente.aniversario":
      parameters = { nome: c.firstName, agencia: d.agencyName };
      break;
    case "viagem.checkin":
      parameters = { nome: c.firstName, destino: d.destination || "sua viagem", data: data(d.tripStart), localizador: d.locator || "-", agencia: d.agencyName };
      break;
    case "viagem.concluida":
      parameters = { nome: c.firstName, destino: d.destination || "sua viagem", agencia: d.agencyName };
      break;
    case "pagamento.vencendo":
      parameters = { nome: c.firstName, valor: brl(d.balanceCents), vencimento: data(d.dueDate), venda: d.saleCode || "", agencia: d.agencyName };
      break;
    case "pagamento.identificado":
      parameters = { nome: c.firstName, valor: brl(d.paidCents), venda: d.saleCode || "", agencia: d.agencyName };
      break;
    default:
      continue;
  }
  out.push({ json: { from: CANAL, to, templateId, parameters, evento: body.type, cliente: c.name, teste: !!body.test } });
}
return out;
